    speed: 28 + G.rnd() * 26, target: null,
    shirt: SHIRTS[Math.floor(G.rnd() * SHIRTS.length)],
    pants: PANTS[Math.floor(G.rnd() * PANTS.length)],
    flee: 0, walkPhase: G.rnd() * 10, scared: false,
  };
}

export function spawnPeds(G, count = 26) {
